/* ---------- L4M4 — Antennas and AP placement ---------- */
function renderC11Antenna(){return c11P('cvs',
  'Where the signal goes is set not just by power but mainly by the <b>antenna</b>. Types: an <b>omnidirectional (omni)</b> radiates all around itself (like candlelight) – the typical home one; a <b>directional</b> one concentrates the signal into a <b>narrow beam</b> one way and comes in several forms – a <b>panel/patch</b> (a room, a corridor), a <b>sector</b> antenna (a wedge, say 90° from a building corner) and a <b>Yagi/dish</b> (a narrow long-range beam for a <b>building-to-building link</b>). An antenna’s strength is given as <b>gain in dBi</b> – a comparison against an imaginary perfect ball that shines <b>equally in every direction</b> (an isotropic radiator). The catch: higher gain <b>adds no energy</b>, it only <b>redistributes</b> it – it flattens the signal ‘doughnut’ sideways at the cost of reach up and down. +3 dBi roughly <b>doubles</b> the power in a given direction but takes it away elsewhere. How ‘wide’ that beam is is called the <b>beamwidth</b>. That is why an AP hangs <b>on the ceiling in the middle of the room</b>, not upright in a corner. And mind the physics: a ceiling AP needs power – <b>PoE</b> solves it (power over the data cable, from the Switch-in-depth course): one Ethernet carries data and current, no socket at the ceiling. Practical rules: put the AP <b>higher and central</b>, away from <b>metal, mirrors and water</b> (a boiler, an aquarium), and confirm the layout with a <b>site survey</b> – by measuring, not guessing.',
  [['gain (dBi)','antenna strength vs an isotropic ball; +3 dBi ≈ 2× power one way, taken from elsewhere.'],['directional vs omni','omni all around (home); directional (panel/sector/Yagi) a narrow beam far.'],['PoE','power over the data cable – one Ethernet carries data and current (powers a ceiling AP).']]);}
function mountC11Antenna(){c11Mount('cvs',[
  {glow:c11g('ap2','--green')+c11g('mob','--green'),dyn:'<g style="stroke:var(--green);stroke-width:1.4;stroke-dasharray:3 3"><line x1="248" y1="142" x2="274" y2="116"/><line x1="212" y1="142" x2="186" y2="116"/><line x1="248" y1="178" x2="274" y2="204"/><line x1="212" y1="178" x2="186" y2="204"/></g>'+c11pkt('M 214 160 L 96 160','--green')+c11lbl(155,110,'omni: all around','--green'),cap:'An <b>omni</b> antenna shines <b>all around</b> – ideal in the middle of a room for even coverage.'},
  {glow:c11g('ap1','--cyan')+c11g('r','--cyan')+c11g('net','--cyan'),dyn:c11pkt('M 245 61 L 385 105','--cyan')+c11lbl(300,211,'directional: a narrow beam far','--cyan'),cap:'A <b>directional</b> antenna focuses the signal into a <b>narrow beam</b> – a building link or a long corridor.'},
  {glow:c11g('ap1','--amber')+c11g('r','--amber'),dyn:'<circle cx="420" cy="190" r="13" style="fill:none;fill-opacity:0;stroke:var(--muted);stroke-width:1.2;stroke-dasharray:2 3"/><ellipse cx="540" cy="190" rx="30" ry="6" style="fill:none;fill-opacity:0;stroke:var(--amber);stroke-width:1.2;stroke-dasharray:2 3"/><line x1="450" y1="190" x2="500" y2="190" style="stroke:var(--muted);stroke-width:1.2"/><ellipse cx="230" cy="56" rx="60" ry="14" style="fill:none;fill-opacity:0;stroke:var(--amber);stroke-width:1.2;stroke-dasharray:3 3"/>'+c11pkt('M 385 105 L 245 61','--amber')+c11lbl(155,110,'higher gain = flatter, not stronger','--amber')+c11lbl(480,166,'no gain → with gain: same energy, different shape','--muted')+c11lbl(310,20,'PoE: the same cable carries data and power','--amber'),cap:'<b>Gain (dBi)</b> adds no energy – the total transmit power is fixed (and capped by regulation); the antenna just redistributes it, flattening it sideways at the cost of up/down reach. So put the AP <b>on the ceiling</b>, not upright in a corner – and <b>PoE</b> brings it power over the same data cable.'}
]);}
/* ---------- L4M5 — MIMO, streams and beamforming ---------- */
function renderC11Mimo(){return c11P('cvw',
  'On a router you read ‘<b>AX3000</b>’ or ‘<b>4×4</b>’ – what is that? Newer Wi-Fi can send <b>several data streams at once</b> using <b>multiple antennas</b>; it is called <b>MIMO</b> (Multiple-In, Multiple-Out). The notation <b>2×2, 3×3, 4×4</b> means the number of <b>transmit × receive</b> chains (antennas). Each pair handles one <b>spatial stream</b> – the streams do not mix like a collision, because each travels to the receiver along a slightly different path (wall reflections) and a multi-antenna receiver can mathematically untangle them. How? Each stream bounces off different walls on the way, so it reaches every receive antenna with a slightly different delay and strength – that is its <b>‘fingerprint’</b>. The receiver measures those fingerprints in advance from a known opening part of the frame and then subtracts the individual streams out of the mixed signal by them, much as you can tell which of two voices comes from the left and which from the right. So <b>4×4</b> = up to four streams at once = roughly four times the throughput of one. The catch: <b>the weaker end sets the speed</b> – if the router is 4×4 but the phone is only 2×2, it runs at 2×2 (phones usually have 1–2 antennas for space and battery). Two clever techniques on top: <b>beamforming</b> – the AP <b>aims</b> energy straight at the client instead of all around (like a flashlight rather than a candle), so the signal is stronger at the edge; and <b>MU-MIMO</b> (Multi-User) – the AP talks to <b>several clients at once</b> on different streams instead of making them queue (Wi-Fi 5 did it only toward clients, Wi-Fi 6 both ways and together with OFDMA). And isn’t MIMO the same thing as OFDMA? It is not – both help serve more clients at once, but from a <b>different raw material</b>: MIMO divides <b>space</b> (more antennas = more simultaneous streams on the same frequency), whereas OFDMA divides <b>frequency</b> (one transmission sliced into parts of the band). Wi-Fi 6 uses them <b>together</b>. The point: the ‘higher number’ on the box is mostly about <b>more devices at once</b>, not a record for one phone.',
  [['MIMO','multiple antennas carry several data streams at once; 2×2/4×4 = transmit×receive chains.'],['spatial stream','one independent data stream over one antenna pair; more streams = higher throughput.'],['beamforming','the AP aims energy straight at the client (stronger at the edge) instead of all around.'],['MU-MIMO','the AP serves several clients at once on different streams, not in a queue (Wi-Fi 5 down, Wi-Fi 6 both ways).']]);}
function mountC11Mimo(){c11Mount('cvw',[
  {glow:c11g('ap2','--blue')+c11g('mob','--blue'),dyn:c11pkt('M 96 160 L 214 160','--blue')+c11lbl(155,110,'1×1: '+'one stream','--blue'),cap:'One antenna = <b>one stream</b>. The base MIMO builds on.'},
  {glow:c11g('ap2','--green')+c11g('mob','--green'),dyn:c11pkt('M 96 156 L 214 156','--green')+c11pkt('M 96 164 L 214 164','--green')+c11lbl(155,110,'4×4: '+'many streams at once','--green'),cap:'<b>MIMO 4×4</b>: more antennas = more <b>spatial streams</b> at once ≈ more throughput. But the <b>weaker end</b> sets it (a phone is often 2×2).'},
  {glow:c11g('ap1','--violet')+c11g('lap','--violet'),dyn:c11pkt('M 214 56 L 96 56','--violet')+c11lbl(155,110,'beamforming: aims at the client','--violet'),cap:'<b>Beamforming</b>: the AP <b>aims</b> energy straight at the client (a flashlight, not a candle) – stronger signal where you read it.'},
  {glow:c11g('ap2','--cyan')+c11g('mob','--cyan')+c11g('lap','--cyan'),dyn:c11lbl(155,110,'MU-MIMO: several clients at once','--cyan'),cap:'<b>MU-MIMO</b>: the AP talks to <b>several clients at once</b> on different streams – a shorter air queue (Wi-Fi 6 both ways, with OFDMA).'}
]);}

